verify.cmd:
node -e 'const fs = require("fs")
const fail = (m) => { console.error(m); process.exit(1) }
const code = fs.readFileSync("lib/qr/node-code.ts", "utf8")
const verify = fs.readFileSync("lib/engagement/verify.ts", "utf8")
if (!/created\s*>=\s*SIGNED_NODE_CODES_SINCE\)\s*return\s*\x27refused\x27/.test(code)) fail("SCAN-646: nodeCodeVerdict no longer refuses the no-code legacy path for a node created after signing shipped, so a node created after LIVE-688 (which gets no random secret) checks in a bare /n/<id> until 2026-12-01.")
if (!/nodeCreatedAt:\s*node\.created_at/.test(verify) || !/select\([^)]*created_at/.test(verify)) fail("SCAN-646: verifyCapture does not pass nodes.created_at into nodeCodeVerdict, so the post-signing refusal never fires.")
'
